keyframes.verbatim:
@keyframes float1 {
  0%,
  to {
    transform: rotate(-8deg) translateY(0);
  }
  50% {
    transform: rotate(-8.6deg) translateY(-12px);
  }
}

@keyframes float2 {
  0%,
  to {
    transform: rotate(7deg) translateY(0);
  }
  50% {
    transform: rotate(7.6deg) translateY(-16px);
  }
}

@keyframes floatBadge {
  0%,
  to {
    transform: rotate(2.5deg) translateY(0);
  }
  50% {
    transform: rotate(3deg) translateY(-7px);
  }
}

@keyframes glodPulse {
  0%,
  to {
    opacity: 0.85;
    transform: scale(1);
  }
  50% {
    opacity: 1;
    transform: scale(1.25);
  }
}

@keyframes glodMemBob {
  0%,
  to {
    transform: translateY(0) rotate(0);
  }
  50% {
    transform: translateY(-5px) rotate(0.4deg);
  }
}

@keyframes glodEmberBreath {
  0%,
  to {
    transform: scale(1);
    box-shadow:
      0 0 10px 3px #ffc373f2,
      0 0 26px 9px #ff983e8c,
      0 0 52px 20px #ff823240;
  }
  50% {
    transform: scale(1.25);
    box-shadow:
      0 0 12px 4px #ffcd7d,
      0 0 34px 12px #ffa044a6,
      0 0 64px 26px #ff84344d;
  }
}

@keyframes glodActiveEmberGlow {
  0%,
  to {
    opacity: 0.88;
    filter: brightness(0.96);
  }
  50% {
    opacity: 1;
    filter: brightness(1.2);
  }
}

@keyframes tfStartIn {
  0% {
    opacity: 0;
    transform: translateY(22px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes tfBrushBob {
  0%,
  to {
    transform: rotate(-8deg) translateY(0);
  }
  50% {
    transform: rotate(6deg) translateY(-5px);
  }
}

@keyframes tfRise {
  0% {
    opacity: 0;
    transform: translate(0);
  }
  12% {
    opacity: 0.95;
  }
  to {
    opacity: 0;
    transform: translate(var(--x, 0), var(--y, -180px));
  }
}

@keyframes tfVeilBreathe {
  0%,
  to {
    opacity: 0.42;
    transform: scale(1);
  }
  50% {
    opacity: 0.9;
    transform: scale(1.06);
  }
}

@keyframes tfVeilDrift {
  0% {
    opacity: 0;
    transform: translateY(0) scale(0.75);
  }
  20% {
    opacity: 0.55;
  }
  50% {
    opacity: 0.7;
    transform: translateY(-28px) scale(1);
  }
  80% {
    opacity: 0.3;
  }
  to {
    opacity: 0;
    transform: translateY(-56px) scale(0.7);
  }
}

@keyframes tfUnveilPop {
  0% {
    transform: scale(0.92);
    box-shadow: 0 0 #f5c54200;
  }
  45% {
    transform: scale(1.06);
    box-shadow: 0 0 26px #f5c5428c;
  }
  to {
    transform: scale(1);
    box-shadow: 0 0 #f5c54200;
  }
}

reduced_motion.verbatim:
@media (prefers-reduced-motion: reduce) {
  .fb1,
  .fb2,
  .badge,
  .dotpulse,
  .starfield {
    animation: none;
  }
  body,
  .bg,
  .tt,
  .tt-thumb,
  .tt-opt {
    transition: none;
  }
  .reveal {
    opacity: 1;
    transition: none;
    transform: none;
  }
  .comp-chosen {
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hiw-map .map-path-lit--lit,
  .hiw-map .map-path-lit--fading,
  .hiw-map .map-medallion {
    transition: none;
  }
  .hiw-memory-tag .dotpulse {
    animation: none;
  }
  .hiw-play,
  .hiw-play:hover {
    transition: none;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .glod-pulse-dot,
  .glod-wb-steps li.active .dot {
    animation: none;
  }
  .glod-active-ember {
    transition: none;
  }
  .glod-active-ember-core,
  .glod-mem-float,
  .glod-mem-ember.on .glod-mem-ember-core {
    animation: none;
  }
  .glod-book {
    transition: opacity 0.4s;
    transform: none;
  }
  .glod-book.show {
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .start-flow .start-screen,
  .start-flow .gallery.open,
  .start-flow .paintpill,
  .start-flow .reveal-line.on,
  .start-flow .reveal-name.on,
  .start-flow .reveal-actions.on,
  .start-flow .sheet {
    animation: none;
  }
  .start-flow .adv,
  .start-flow .adv:hover {
    transition: none;
    transform: none;
  }
  .start-flow .paintpill .dotpulse,
  .start-flow .pframe .veil svg {
    animation: none;
  }
  .start-flow .easel img {
    transition: opacity 0.2s;
  }
  .start-flow .embers.go .ember,
  .start-flow .unveil-armed.ready-pop {
    animation: none;
  }
  .start-flow .easel .veil-glow {
    opacity: 0.6;
    animation: none;
  }
  .start-flow .veil-speck {
    opacity: 0.4;
    animation: none;
  }
  .start-flow .veil-caption {
    opacity: 1;
    animation: none;
  }
}
